const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Mount Fuji location
  const mtFuji = ee.Geometry.Point([138.73, 35.36]).buffer(5000);

  // Function to calculate NDSI for Landsat
  function addNDSI(image) {
    const ndsi = image.normalizedDifference(['B3', 'B6']).rename('NDSI'); // Green and SWIR1
    return image.addBands(ndsi);
  }

  // Cloud mask for Landsat 5/7
  function maskCloudsL57(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(mask);
  }

  // Cloud mask for Landsat 8
  function maskCloudsL8(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(mask);
  }

  // Function to get mean NDSI for a December
  async function getDecemberNDSI(year) {
    const startDate = `${year}-12-01`;
    const endDate = `${year}-12-31`;

    let collection;
    if (year <= 2011) {
      // Use Landsat 5
      collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(mtFuji)
        .filterDate(startDate, endDate)
        .map(maskCloudsL57)
        .map(addNDSI);
    } else if (year <= 2013) {
      // Use Landsat 7
      collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterBounds(mtFuji)
        .filterDate(startDate, endDate)
        .map(maskCloudsL57)
        .map(addNDSI);
    } else {
      // Use Landsat 8
      collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(mtFuji)
        .filterDate(startDate, endDate)
        .map(maskCloudsL8)
        .map(addNDSI);
    }

    const size = collection.size().getInfo();
    if (size === 0) {
      return { mean: null, count: 0, size: 0 };
    }

    const meanImage = collection.select('NDSI').mean();
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: mtFuji,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    return {
      mean: stats['NDSI_mean'],
      count: stats['NDSI_count'],
      size: size
    };
  }

  // Get December 2020 NDSI
  console.log("Analyzing December 2020...");
  const dec2020 = await getDecemberNDSI(2020);
  console.log(`Dec 2020: Images=${dec2020.size}, Pixels=${dec2020.count}, NDSI=${dec2020.mean}`);

  if (dec2020.size === 0) {
    console.log("No data for December 2020");
    console.log("<answer>C1</answer>");
    return;
  }

  if (dec2020.count === 0) {
    console.log("No valid pixels for December 2020");
    console.log("<answer>C2</answer>");
    return;
  }

  if (dec2020.mean === null || dec2020.mean === undefined || isNaN(dec2020.mean)) {
    console.log("Invalid calculation for December 2020");
    console.log("<answer>C3</answer>");
    return;
  }

  // Get NDSI for each December 2005-2015
  const years = [];
  for (let year = 2005; year <= 2015; year++) {
    years.push(year);
  }

  let allValid = true;
  let dec2020IsLowest = true;

  for (const year of years) {
    const decStats = await getDecemberNDSI(year);
    console.log(`Dec ${year}: Images=${decStats.size}, Pixels=${decStats.count}, NDSI=${decStats.mean}`);

    if (decStats.size === 0 || decStats.count === 0 || decStats.mean === null || isNaN(decStats.mean)) {
      allValid = false;
      continue;
    }

    if (dec2020.mean >= decStats.mean) {
      dec2020IsLowest = false;
    }
  }

  if (!allValid) {
    console.log("Missing data for some years");
    console.log("<answer>C1</answer>");
    return;
  }

  console.log(`\nDec 2020 NDSI (${dec2020.mean.toFixed(3)}) is lowest: ${dec2020IsLowest}`);

  if (dec2020IsLowest) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
